-- Rebuild Medina Book 4 lesson 16 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 64-68. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '16';
  if existing_count = 2 then
    update public.rules
    set sort_order = 4
    where course_name = 'Мединский курс (Том 4)'
      and lesson_number = '16'
      and sort_order = 2;

    insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
    values
      ('Мединский курс (Том 4)', '16', '__book4_lesson16_endings__', '', 2, 'rule', '', null),
      ('Мединский курс (Том 4)', '16', '__book4_lesson16_irab__', '', 3, 'rule', '', null);
  elsif existing_count <> 4 then
    raise exception 'Expected 2 legacy or 4 rebuilt Book 4 lesson 16 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'تَوْكِيدُ الْأَفْعَالِ بِنُونِ التَّوْكِيدِ (усиление глаголов нуном усиления)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">نُونُ التَّوْكِيدِ نَوْعَانِ: ثَقِيلَةٌ وَخَفِيفَةٌ. لَا يُؤَكَّدُ الْفِعْلُ الْمَاضِي بِنُونِ التَّوْكِيدِ، وَإِنَّمَا يُؤَكَّدُ بِقَدْ، وَيَجُوزُ تَوْكِيدُ فِعْلِ الْأَمْرِ مُطْلَقًا. أَمَّا الْمُضَارِعُ فَيَجُوزُ تَوْكِيدُهُ إِذَا سُبِقَ بِطَلَبٍ، وَيَكُونُ قَرِيبًا مِنَ الْوُجُوبِ بَعْدَ إِمَّا الشَّرْطِيَّةِ، وَيَجِبُ إِذَا كَانَ جَوَابًا لِلْقَسَمِ مُتَّصِلًا بِلَامِ جَوَابِ الْقَسَمِ مُثْبَتًا مُسْتَقْبَلًا، وَيَمْتَنِعُ إِذَا فُقِدَ شَرْطٌ مِنْ هَذِهِ الشُّرُوطِ.</span><p class="rule-study-text">Шарх различает тяжёлый и лёгкий нун усиления, затем отдельно устанавливает правило для прошедшего, повелительного и четыре состояния настоящего-будущего глагола: допустимость, близость к обязательности, обязательность и запрет.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два вида нуна усиления</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">форма</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ثَقِيلَةٌ</span><span class="rule-table-ru">тяжёлая</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نَّ</span><span class="rule-table-ru">буква нун с шаддой и фатхой</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِذْهَبَنَّ</span><span class="rule-table-ru">непременно иди</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">خَفِيفَةٌ</span><span class="rule-table-ru">лёгкая</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نْ</span><span class="rule-table-ru">буква нун с сукуном</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِذْهَبَنْ</span><span class="rule-table-ru">непременно иди</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Прошедший и повелительный глаголы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْفِعْلُ</span><span class="rule-table-ru">глагол</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">правило</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедший</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَا يُؤَكَّدُ بِنُونِ التَّوْكِيدِ، وَإِنَّمَا يُؤَكَّدُ بِقَدْ</span><span class="rule-table-ru">нун усиления не присоединяется; усиление выражает частица «кад»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">قَدْ ذَهَبَ.</span><span class="rule-table-ru">Он действительно ушёл.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повелительный</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَجُوزُ تَوْكِيدُهُ مُطْلَقًا بِلَا شَرْطٍ</span><span class="rule-table-ru">усиление разрешено без условия</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِذْهَبَنَّ؛ اِذْهَبَنْ.</span><span class="rule-table-ru">Непременно иди — с тяжёлым или лёгким нуном.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре состояния настоящего-будущего глагола</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">степень правила</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الشَّرْطُ</span><span class="rule-table-ru">условие</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">جَائِزٌ</span><span class="rule-table-ru">допустимо</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِذَا سُبِقَ بِطَلَبٍ</span><span class="rule-table-ru">если перед ним побуждение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هَلْ تُسَافِرَنَّ وَأَنْتَ مَرِيضٌ؟ لِيَقْرَأَنَّ كُلُّ طَالِبٍ دَرْسَهُ؛ هَلَّا تَجْتَهِدَنَّ؛ لَا تُهْمِلَنَّ دُرُوسَكَ.</span><span class="rule-table-ru">Неужели ты поедешь больным? Пусть каждый студент обязательно прочитает урок; отчего бы тебе непременно не постараться; ни в коем случае не запускай уроки.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">قَرِيبٌ مِنَ الْوَاجِبِ</span><span class="rule-table-ru">близко к обязательному</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِذَا وَقَعَ بَعْدَ إِمَّا الشَّرْطِيَّةِ</span><span class="rule-table-ru">если стоит после условной частицы «имма»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِمَّا تُسَافِرَنَّ إِلَى مَكَّةَ أُسَافِرْ مَعَكَ.</span><span class="rule-table-ru">Если ты непременно поедешь в Мекку, я поеду с тобой.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">وَاجِبٌ</span><span class="rule-table-ru">обязательно</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">جَوَابُ قَسَمٍ مُتَّصِلٌ بِلَامِ الْجَوَابِ، مُثْبَتٌ، مُسْتَقْبَلٌ</span><span class="rule-table-ru">ответ клятвы, непосредственно после ляма ответа клятвы, утвердительный и будущий</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَاللَّهِ لَأَجْتَهِدَنَّ.</span><span class="rule-table-ru">Клянусь Аллахом, я непременно буду усердствовать.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُمْتَنِعٌ</span><span class="rule-table-ru">запрещено</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِذَا لَمْ يَتَحَقَّقْ شَرْطٌ مِنَ الشُّرُوطِ السَّابِقَةِ</span><span class="rule-table-ru">если отсутствует одно из трёх условий обязательного усиления</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَاللَّهِ لَسَوْفَ أَجْتَهِدُ؛ وَاللَّهِ لَا أُدَخِّنُ؛ وَاللَّهِ لَأَخْرُجُ الْآنَ.</span><span class="rule-table-ru">Усиление запрещено соответственно из-за разрыва частицей «сауфа», отрицания и значения настоящего времени.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Происхождение условной частицы «имма»</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">إِنْ الشَّرْطِيَّةُ + مَا الزَّائِدَةُ</span><span class="rule-term-ru">условная частица «ин» вместе с добавочной частицей «ма»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры четырёх контекстов</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢا﴾</span><span class="rule-example-ru">Не считай погибших на пути Аллаха мёртвыми: усиление после запретительного побуждения.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى﴾</span><span class="rule-example-ru">Если непременно придёт к вам от Меня руководство: усиление после условной частицы «имма».</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَإِمَّا نُرِيَنَّكَ﴾</span><span class="rule-example-ru">И если Мы непременно покажем тебе: второй пример усиления после условной частицы «имма».</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم﴾</span><span class="rule-example-ru">Клянусь Аллахом, я непременно устрою замысел против ваших идолов: обязательное усиление в ответе клятвы.</span></div></div></div></div>', 'Шарх различает тяжёлый и лёгкий нун усиления, затем отдельно устанавливает правило для прошедшего, повелительного и четыре состояния настоящего-будущего глагола: допустимость, близость к обязательности, обязательность и запрет.', 'نُونُ التَّوْكِيدِ نَوْعَانِ: ثَقِيلَةٌ وَخَفِيفَةٌ. لَا يُؤَكَّدُ الْفِعْلُ الْمَاضِي بِنُونِ التَّوْكِيدِ، وَإِنَّمَا يُؤَكَّدُ بِقَدْ، وَيَجُوزُ تَوْكِيدُ فِعْلِ الْأَمْرِ مُطْلَقًا. أَمَّا الْمُضَارِعُ فَيَجُوزُ تَوْكِيدُهُ إِذَا سُبِقَ بِطَلَبٍ، وَيَكُونُ قَرِيبًا مِنَ الْوُجُوبِ بَعْدَ إِمَّا الشَّرْطِيَّةِ، وَيَجِبُ إِذَا كَانَ جَوَابًا لِلْقَسَمِ مُتَّصِلًا بِلَامِ جَوَابِ الْقَسَمِ مُثْبَتًا مُسْتَقْبَلًا، وَيَمْتَنِعُ إِذَا فُقِدَ شَرْطٌ مِنْ هَذِهِ الشُّرُوطِ.'),
    (2, 'أَحْكَامُ آخِرِ الْفِعْلِ الْمُؤَكَّدِ بِنُونِ التَّوْكِيدِ (изменения окончания глагола с нуном усиления)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">إِذَا اتَّصَلَتْ نُونُ التَّوْكِيدِ بِالْفِعْلِ مُبَاشَرَةً بُنِيَ عَلَى الْفَتْحِ. وَمَعَ وَاوِ الْجَمَاعَةِ تُحْذَفُ نُونُ الرَّفْعِ ثُمَّ الْوَاوُ، وَيُضَمُّ آخِرُ الْفِعْلِ؛ وَمَعَ يَاءِ الْمُخَاطَبَةِ تُحْذَفُ نُونُ الرَّفْعِ ثُمَّ الْيَاءُ، وَيُكْسَرُ آخِرُهُ. وَمَعَ أَلِفِ الِاثْنَيْنِ تُحْذَفُ نُونُ الرَّفْعِ وَتَبْقَى الْأَلِفُ وَتُكْسَرُ نُونُ التَّوْكِيدِ، وَمَعَ نُونِ النِّسْوَةِ تَبْقَى النُّونُ وَتُزَادُ أَلِفٌ فَاصِلَةٌ وَتُكْسَرُ نُونُ التَّوْكِيدِ. وَفِي الْأَمْرِ وَالْجَزْمِ مِنَ الْمُعْتَلِّ الْآخِرِ يُرَدُّ حَرْفُ الْعِلَّةِ الْمَحْذُوفُ.</span><p class="rule-study-text">Окончание зависит от того, соединяется ли нун непосредственно или после формы уже имеются вау группы, йа обращения к женщине, алиф двойственного либо нун женского множественного. Для слабого конечного глагола в повелительном и усечённом настоящем восстанавливается удалённая слабая буква.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Пять способов присоединения</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ الْأَصْلِيَّةُ</span><span class="rule-table-ru">исходная форма</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَا يَحْدُثُ</span><span class="rule-table-ru">изменение</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَعْدَ التَّوْكِيدِ</span><span class="rule-table-ru">усиленная форма</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">حُكْمُ الْفِعْلِ</span><span class="rule-table-ru">состояние глагола</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ بِلَا ضَمِيرٍ بَارِزٍ</span><span class="rule-table-ru">глагол без явного присоединённого местоимения</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اتِّصَالٌ مُبَاشِرٌ بِنُونِ التَّوْكِيدِ</span><span class="rule-table-ru">нун присоединяется непосредственно</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِذْهَبَنَّ؛ لَا تَذْهَبَنَّ؛ يَذْهَبَنَّ؛ اِذْهَبَنْ؛ لَا تَذْهَبَنْ؛ يَذْهَبَنْ.</span><span class="rule-table-ru">формы с тяжёлым и лёгким нуном</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَبْنِيٌّ عَلَى الْفَتْحِ</span><span class="rule-table-ru">неизменяем с фатхой</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">وَاوُ الْجَمَاعَةِ</span><span class="rule-table-ru">групповая вау</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">حَذْفُ نُونِ الرَّفْعِ، ثُمَّ حَذْفُ الْوَاوِ لِالْتِقَاءِ السَّاكِنَيْنِ، وَضَمُّ آخِرِ الْفِعْلِ</span><span class="rule-table-ru">удаляются нун именительного и вау группы; конец получает дамму</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَذْهَبُنَّ؛ يَذْهَبُنْ.</span><span class="rule-table-ru">они непременно пойдут</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُعْرَبٌ</span><span class="rule-table-ru">остаётся изменяемым</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">يَاءُ الْمُخَاطَبَةِ</span><span class="rule-table-ru">йа обращения к женщине</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">حَذْفُ نُونِ الرَّفْعِ، ثُمَّ حَذْفُ الْيَاءِ لِالْتِقَاءِ السَّاكِنَيْنِ، وَكَسْرُ آخِرِ الْفِعْلِ</span><span class="rule-table-ru">удаляются нун именительного и йа; конец получает касру</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَذْهَبِنَّ؛ تَذْهَبِنْ.</span><span class="rule-table-ru">ты, женщина, непременно пойдёшь</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُعْرَبٌ</span><span class="rule-table-ru">остаётся изменяемым</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَلِفُ الِاثْنَيْنِ</span><span class="rule-table-ru">алиф двойственного</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">حَذْفُ نُونِ الرَّفْعِ، وَبَقَاءُ الْأَلِفِ، وَكَسْرُ نُونِ التَّوْكِيدِ</span><span class="rule-table-ru">нун именительного удаляется, алиф сохраняется, нун усиления получает касру</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَذْهَبَانِّ.</span><span class="rule-table-ru">они двое непременно пойдут</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُعْرَبٌ؛ لَا تَتَّصِلُ بِهِ النُّونُ الْخَفِيفَةُ</span><span class="rule-table-ru">изменяем; лёгкий нун не присоединяется</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">نُونُ النِّسْوَةِ</span><span class="rule-table-ru">нун женского множественного</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">بَقَاءُ نُونِ النِّسْوَةِ، وَزِيَادَةُ أَلِفٍ فَاصِلَةٍ، وَكَسْرُ نُونِ التَّوْكِيدِ</span><span class="rule-table-ru">нун женского сохраняется, вставляется разделительный алиф, нун усиления получает касру</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَذْهَبْنَانِّ.</span><span class="rule-table-ru">они, женщины, непременно пойдут</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَبْنِيٌّ عَلَى السُّكُونِ؛ لَا تَتَّصِلُ بِهِ النُّونُ الْخَفِيفَةُ</span><span class="rule-table-ru">неизменяем с сукуном; лёгкий нун не присоединяется</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Восстановление слабой буквы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْفِعْلُ</span><span class="rule-table-ru">глагол</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْرُ مَعَ التَّوْكِيدِ</span><span class="rule-table-ru">повелительный с усилением</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَجْزُومُ مَعَ التَّوْكِيدِ</span><span class="rule-table-ru">усечённый настоящий с усилением</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفُ الْعِلَّةِ الْمَرْدُودُ</span><span class="rule-table-ru">восстановленная буква</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دَعَا ـ يَدْعُو</span><span class="rule-table-ru">звать</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اُدْعُوَنَّ</span><span class="rule-table-ru">непременно зови</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا تَدْعُوَنَّ</span><span class="rule-table-ru">ни в коем случае не зови</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَاوُ</span><span class="rule-table-ru">вау</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رَمَى ـ يَرْمِي</span><span class="rule-table-ru">бросать</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِرْمِيَنَّ</span><span class="rule-table-ru">непременно бросай</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا تَرْمِيَنَّ</span><span class="rule-table-ru">ни в коем случае не бросай</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْيَاءُ</span><span class="rule-table-ru">йа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَعَى ـ يَسْعَى</span><span class="rule-table-ru">стремиться</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْعَيَنَّ</span><span class="rule-table-ru">непременно стремись</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا تَسْعَيَنَّ</span><span class="rule-table-ru">ни в коем случае не стремись</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْيَاءُ</span><span class="rule-table-ru">йа, возвращённая вместо алифа</span></td></tr></tbody></table></div></div></div>', 'Окончание зависит от того, соединяется ли нун непосредственно или после формы уже имеются вау группы, йа обращения к женщине, алиф двойственного либо нун женского множественного. Для слабого конечного глагола в повелительном и усечённом настоящем восстанавливается удалённая слабая буква.', 'إِذَا اتَّصَلَتْ نُونُ التَّوْكِيدِ بِالْفِعْلِ مُبَاشَرَةً بُنِيَ عَلَى الْفَتْحِ. وَمَعَ وَاوِ الْجَمَاعَةِ تُحْذَفُ نُونُ الرَّفْعِ ثُمَّ الْوَاوُ، وَيُضَمُّ آخِرُ الْفِعْلِ؛ وَمَعَ يَاءِ الْمُخَاطَبَةِ تُحْذَفُ نُونُ الرَّفْعِ ثُمَّ الْيَاءُ، وَيُكْسَرُ آخِرُهُ. وَمَعَ أَلِفِ الِاثْنَيْنِ تُحْذَفُ نُونُ الرَّفْعِ وَتَبْقَى الْأَلِفُ وَتُكْسَرُ نُونُ التَّوْكِيدِ، وَمَعَ نُونِ النِّسْوَةِ تَبْقَى النُّونُ وَتُزَادُ أَلِفٌ فَاصِلَةٌ وَتُكْسَرُ نُونُ التَّوْكِيدِ. وَفِي الْأَمْرِ وَالْجَزْمِ مِنَ الْمُعْتَلِّ الْآخِرِ يُرَدُّ حَرْفُ الْعِلَّةِ الْمَحْذُوفُ.'),
    (3, 'إِعْرَابُ الْفِعْلِ الْمُؤَكَّدِ بِنُونِ التَّوْكِيدِ (разбор глагола с нуном усиления)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-predicate" dir="rtl" lang="ar">الْفِعْلُ الْمُتَّصِلُ بِنُونِ التَّوْكِيدِ مُبَاشَرَةً يُبْنَى عَلَى الْفَتْحِ، وَتَكُونُ النُّونُ الثَّقِيلَةُ حَرْفًا مَبْنِيًّا عَلَى الْفَتْحِ، وَالْخَفِيفَةُ حَرْفًا مَبْنِيًّا عَلَى السُّكُونِ، وَلَا مَحَلَّ لِكِلْتَيْهِمَا مِنَ الْإِعْرَابِ. أَمَّا الْمُضَارِعُ الْمُتَّصِلُ أَصْلًا بِوَاوِ الْجَمَاعَةِ فَيَبْقَى مُعْرَبًا، وَتُقَدَّرُ عَلَامَةُ رَفْعِهِ بِنُونِ الرَّفْعِ الْمَحْذُوفَةِ.</span><p class="rule-study-text">Шарх полностью разбирает три формы: настоящий с прямым тяжёлым нуном, повелительный с прямым лёгким нуном и настоящий с удалённой вау группы перед тяжёлым нуном.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три полных разбора</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">форма</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِعْرَابُ الْفِعْلِ وَالْفَاعِلِ</span><span class="rule-table-ru">разбор глагола и субъекта</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِعْرَابُ نُونِ التَّوْكِيدِ</span><span class="rule-table-ru">разбор нуна усиления</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَذْهَبَنَّ</span><span class="rule-table-ru">он непременно пойдёт</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَبْنِيٌّ عَلَى الْفَتْحِ لِاتِّصَالِهِ مُبَاشَرَةً بِنُونِ التَّوْكِيدِ الثَّقِيلَةِ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ.</span><span class="rule-table-ru">Настоящий глагол неизменяем с фатхой; субъект — скрытое местоимение «он».</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حَرْفٌ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">Тяжёлый нун — частица с фатхой без синтаксической позиции.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِذْهَبَنْ</span><span class="rule-table-ru">непременно иди</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">فِعْلُ أَمْرٍ مَبْنِيٌّ عَلَى الْفَتْحِ لِاتِّصَالِهِ مُبَاشَرَةً بِنُونِ التَّوْكِيدِ الْخَفِيفَةِ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ أَنْتَ.</span><span class="rule-table-ru">Повелительный глагол неизменяем с фатхой; субъект — скрытое местоимение «ты».</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حَرْفٌ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">Лёгкий нун — частица с сукуном без синтаксической позиции.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَذْهَبُنَّ</span><span class="rule-table-ru">они непременно пойдут</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ النُّونُ الْمَحْذُوفَةُ لِتَوَالِي الْأَمْثَالِ، وَوَاوُ الْجَمَاعَةِ الْمَحْذُوفَةُ لِالْتِقَاءِ السَّاكِنَيْنِ فَاعِلٌ فِي مَحَلِّ رَفْعٍ.</span><span class="rule-table-ru">Настоящий глагол в именительном; показатель — удалённый нун, а удалённая вау группы является субъектом.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حَرْفٌ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">Тяжёлый нун — частица с фатхой без синтаксической позиции.</span></td></tr></tbody></table></div></div></div>', 'Шарх полностью разбирает три формы: настоящий с прямым тяжёлым нуном, повелительный с прямым лёгким нуном и настоящий с удалённой вау группы перед тяжёлым нуном.', 'الْفِعْلُ الْمُتَّصِلُ بِنُونِ التَّوْكِيدِ مُبَاشَرَةً يُبْنَى عَلَى الْفَتْحِ، وَتَكُونُ النُّونُ الثَّقِيلَةُ حَرْفًا مَبْنِيًّا عَلَى الْفَتْحِ، وَالْخَفِيفَةُ حَرْفًا مَبْنِيًّا عَلَى السُّكُونِ، وَلَا مَحَلَّ لِكِلْتَيْهِمَا مِنَ الْإِعْرَابِ. أَمَّا الْمُضَارِعُ الْمُتَّصِلُ أَصْلًا بِوَاوِ الْجَمَاعَةِ فَيَبْقَى مُعْرَبًا، وَتُقَدَّرُ عَلَامَةُ رَفْعِهِ بِنُونِ الرَّفْعِ الْمَحْذُوفَةِ.'),
    (4, 'بَلِ الِابْتِدَائِيَّةُ (начальная частица «баль»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">بَلْ حَرْفُ ابْتِدَاءٍ يُفِيدُ الْإِضْرَابَ إِذَا كَانَ مَا بَعْدَهُ جُمْلَةً اسْمِيَّةً أَوْ فِعْلِيَّةً. وَالْإِضْرَابُ نَوْعَانِ: إِبْطَالِيٌّ وَانْتِقَالِيٌّ. وَبَلْ حَرْفٌ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><p class="rule-study-text">Когда после частицы «баль» следует именное или глагольное предложение, она является начальной частицей перехода: либо отменяет предыдущее утверждение, либо переводит речь к следующему смыслу.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два вида смыслового перехода</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">смысл</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِضْرَابٌ إِبْطَالِيٌّ</span><span class="rule-table-ru">отменяющий переход</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِبْطَالُ الْمَعْنَى السَّابِقِ</span><span class="rule-table-ru">предыдущий смысл отвергается</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">لَا تَظُنَّنَّ الْكَسْلَانَ نَاجِحًا، بَلْ هُوَ رَاسِبٌ.</span><span class="rule-table-ru">Не считай лентяя преуспевшим: напротив, он не сдал.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِضْرَابٌ انْتِقَالِيٌّ</span><span class="rule-table-ru">переход к новому смыслу</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الِانْتِقَالُ إِلَى مَعْنًى آخَرَ</span><span class="rule-table-ru">речь переходит к другому смыслу</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">اتَّقُوا اللَّهَ وَأَطِيعُوهُ، بَلْ قُلُوبُكُمْ لَاهِيَةٌ.</span><span class="rule-table-ru">Бойтесь Аллаха и повинуйтесь Ему; однако ваши сердца беспечны.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример отменяющего перехода</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗاۗ سُبۡحَٰنَهُۥۚ بَلۡ عِبَادٞ مُّكۡرَمُونَ﴾</span><span class="rule-example-ru">Они сказали: «Милостивый взял Себе сына». Пречист Он! Напротив, они — почтенные рабы.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример перехода к новому смыслу</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ ۝ وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ ۝ بَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا﴾</span><span class="rule-example-ru">Преуспел очистившийся, помянувший имя Господа и совершивший молитву. Но вы предпочитаете мирскую жизнь.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Разбор частицы</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ ابْتِدَاءٍ مَبْنِيٌّ عَلَى السُّكُونِ</span><span class="rule-term-ru">начальная частица, неизменяемая с сукуном</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ</span><span class="rule-term-ru">не имеет синтаксической позиции</span></div></div></div></div>', 'Когда после частицы «баль» следует именное или глагольное предложение, она является начальной частицей перехода: либо отменяет предыдущее утверждение, либо переводит речь к следующему смыслу.', 'بَلْ حَرْفُ ابْتِدَاءٍ يُفِيدُ الْإِضْرَابَ إِذَا كَانَ مَا بَعْدَهُ جُمْلَةً اسْمِيَّةً أَوْ فِعْلِيَّةً. وَالْإِضْرَابُ نَوْعَانِ: إِبْطَالِيٌّ وَانْتِقَالِيٌّ. وَبَلْ حَرْفٌ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '16'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '16'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ السَّادِسَ عَشَرَ
تَوْكِيدُ الأفعالِ بِنُونِ التَّوْكِيدِ
نونُ التوكيدِ نوعانِ :
أ- ثَقِيلَةٌ .           ب- خَفِيفَةٌ .
أحكامُ توكيدِ الأفعالِ :
1- الماضي : لا يُؤَكَّدُ بنونِ التَّوكيدِ ، وإنّما يُؤَكَّدُ بقَدْ .
2- الأمر : يجوز توكيده مطلقا ، : أي بدون شرط ، نحو : اِذْهَبَنَّ ، اِذْهَبَنْ .
3- المضارع : له أربع حالات :
أ- يجوزُ توكيدُه : وذلك إذا سُبِقَ بِطَلَبٍ ، نحو : هل تُسَافِرَنَّ وأنت مريضٌ ؟
لِيَقْرَأَنَّ كلُّ طالبٍ دَرْسَهُ . هَلاَّ تَجْتَهِدَنَّ . لَا تُهْمِلَنَّ دُرُوسَكَ . ومنه قوله تعالى :
﴿ وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللهِ أَمْوَاتًا ... ﴾ .
ب- قَرِيبٌ مِنَ الواجبِ : وذلك إذا وقع بعد ( إِمَّا ) الشرطية ( أصلها إنْ الشرطية وما الزائدة ) نحو قوله تعالى : ﴿ فَإِمَّا يَأْتِيَنَّكُمْ ﴾ وقوله تعالى : ﴿ وَإِمَّا نُرِيَنَّكَ ﴾ ونحو :         إِمَّا تُسَافِرَنَّ إِلى مَكَّةَ أُسَافِرْ مَعَكَ .
ج- يجبُ توكيدُه : وذلك إذا وقع جواباً للقسم , وكان مُتَّصِلاً بلام جَوَابِ الْقَسَمِ , ومُثْبَتاً ( غيرَ منفيٍّ ) ومُسْتَقْبَلاً ، نحو: واللهِ لأَجْتَهِدَنَّ ، ونحو قوله تعالى :
﴿ وَتَاللهِ لَأَكِيدَنَّ أَصْنَامَكُمْ ﴾ .
د- يمتنعُ توكيدُه : وذلك إذا لم يتحقَّقْ أحدُ الشُّروطِ الثَّلاثةِ السَّابقةِ .
نحو : واللهِ لسوف أجتهدُ . يمتنع توكيده ؛ لكونه مفصولا من لام الجواب بسوف .
ونحو : واللهِ لا أُدَخِّنُ . يمتنع توكيده ؛ لكونه مَنْفِيًّا .
ونحو : واللهِ لأَخْرُجُ الآنَ . يمتنع توكيده ؛ لكونه دالاًّ على الحال .', 64, 65, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '16' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'أحكامُ آخِرِ الفعلِ الْمُؤَكَّدِ بنونِ التَّوكيدِ :
1- إذا اتَّصلتْ نونُ التَّوكيدِ بالفعلِ اتِّصالاً مُباشراً بُنِيَ على الفتحِ .
نحو : اِذْهَبَنَّ - لا تَذْهَبَنَّ - يَذْهَبَنَّ . اِذْهَبَنْ - لا تَذْهَبَنْ - يَذْهَبَنْ .
2- إذا اتصلت نون التوكيد بفعل متَّصل بواو الجماعة حُذِفَتْ نونُ الرَّفعِ لِتَوَالِي الأَمْثَالِ ( أي : تَوَالِي ثلاثِ نُونَاتٍ ) ثم تُحْذَفُ واو الجماعة لالْتِقَاءِ السَّاكِنَيْنِ , ويُضَمُّ آخِرُ الفعلِ لِلدَّلَالَةِ على أنّ المحذوفَ واوُ الجماعةِ , نحو : يَذْهَبُنَّ ، ويَذْهَبُنْ .
ويكونُ الفعلُ مُعْرَباً .
3- إذا اتَّصلت نون التوكيد بفعل متَّصل بياء المخاطَبة حُذفتْ نونُ الرَّفعِ لتوالي الأمثالِ ، ثم تُحذفُ ياءُ المخاطَبةِ لالتقاءِ السَّاكنين ، ويُكْسَرُ آخِرُ الفعلِ للدَّلالة على أنّ المحذوف ياء المخاطبة , نحو : تَذْهَبِنَّ ، وتَذْهَبِنْ . ويكون معرباً أيضاً .
4- إذا اتصلت نون التوكيد بفعل متصل بألف الاثنين حُذفت نون الرفع لتوالي الأمثال ، ولا تُحذف ألف الاثنين ( لِئَلاَّ يلْتَبِسَ بالمفرد ) وتُكْسَرُ نون التوكيد , نحو : يَذْهَبَانِّ .
وهو معربٌ أيضاً . ولا يجوز أن تتَّصل به النُّون الخفيفة .
5- إذا اتصلت نون التوكيد بفعل متصل بنون النَّسْوةِ لا تحذف نون النسوة , وتُزَادُ ألفٌ فَاصِلَةٌ ( لِلْفَصْلِ بين نون النِّسوة ونون التَّوكيد ) وتُكْسَرُ نون التوكيد ( تَشْبِيهاً لها بالمثنى ) نحو يَذْهَبْنَانِّ .
وهو مبنيٌّ على السُّكون لِاتِّصَالِهِ بنون النَّسْوَة . ولا يجوز أن تتصل به النون الخفيفة .
6- إذا أردنا توكيدَ الفعلِ المعتلِّ الآخِرِ بنون التَّوكيد في حالتي الجزم ، والأمر رَدَدْنَا حرفَ الْعِلَّةِ المحذوفَ , نحو :   اُدْعُ : اُدْعُوَنَّ  .      لا تَدْعُ : لا تَدْعُوَنَّ
اِرْمِ : اِرْمِيَنَّ  .        لا تَرْمِ : لا تَرْمِيَنَّ .
اِسْعَ : اِسْعَيَنَّ .       لا تَسْعَ : لا تَسْعَيَنَّ', 65, 66, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '16' and sort_order = 2;

